package dev.admutium.techmod.client.suit;
import dev.admutium.techmod.suit.*;import dev.admutium.techmod.energy.Energy;
import net.fabricmc.fabric.api.client.networking.v1.ClientPlayNetworking;
import net.minecraft.client.gui.*;import net.minecraft.client.gui.components.*;import net.minecraft.client.gui.screens.inventory.AbstractContainerScreen;import net.minecraft.client.input.MouseButtonEvent;import net.minecraft.network.chat.Component;import net.minecraft.world.entity.player.Inventory;import net.minecraft.world.item.*;import net.minecraft.core.registries.BuiltInRegistries;
import java.util.*;
public final class SuitStationScreen extends AbstractContainerScreen<SuitStationMenu> {
 private final Map<Button,SuitUpgrade> upgrades=new LinkedHashMap<>();
 private String branch="storage",filter="";private EditBox search;private List<Item> catalog=List.of();private int page;
 public SuitStationScreen(SuitStationMenu menu,Inventory inv,Component title){super(menu,inv,title,360,240);inventoryLabelX=12;inventoryLabelY=136;titleLabelX=12;titleLabelY=10;}
 void send(String key,String value){ClientPlayNetworking.send(new SuitPackets.Action(key,value,menu.containerId));}
 void button(String text,int x,int y,int w,Runnable action){addRenderableWidget(Button.builder(Component.literal(text),b->action.run()).bounds(leftPos+x,topPos+y,w,18).build());}
 @Override protected void init(){super.init();upgrades.clear();button("Создать прототип",36,29,140,()->send("create",""));button("Надеть",12,69,78,()->send("equip",""));button("Снять",94,69,82,()->send("remove",""));button("Открыть всё бесплатно",12,89,164,()->send("all",""));button("Капсулы / вернуть вещи",12,109,164,()->send(SuitClient.data.sealed()?"recover":"feed",""));button("Цвет",12,127,48,()->{filter="color";rebuildWidgets();});button("Фильтр",64,127,54,()->{filter="blacklist";rebuildWidgets();});button("Руды",122,127,54,()->{filter="ores";rebuildWidgets();});
  for(int i=0;i<8;i++){String id=SuitUpgrade.BRANCHES[i];addRenderableWidget(Button.builder(Component.translatable("suit.branch."+id),b->{branch=id;filter="";rebuildWidgets();}).bounds(leftPos+184+(i%4)*42,topPos+29+(i/4)*20,40,18).build());}
  if(filter.isEmpty()){int row=0;for(var u:SuitUpgrade.values())if(u.branch.equals(branch)){int y=74+row++*17;var button=addRenderableWidget(Button.builder(Component.translatable("suit.upgrade."+u.id()),b->send("upgrade",u.id())).bounds(leftPos+184,topPos+y,168,16).build());upgrades.put(button,u);}}
  else{search=new EditBox(font,leftPos+184,topPos+74,168,18,Component.literal("Название / mod:id / HEX"));search.setMaxLength(128);search.setResponder(this::query);addRenderableWidget(search);query("");if(filter.equals("color")){button("Применить #RRGGBB",184,98,168,()->send("color",search.getValue()));button("Оранжевый",184,121,168,()->send("color","ff9c26"));}else{button("←",184,188,30,()->page=Math.max(0,page-1));button("→",322,188,30,()->{if((page+1)*32<catalog.size())page++;});}}
  button("Радиус магнита",12,226,164,()->send("range",Integer.toString((SuitClient.data.magnetRange()+1)%4)));
 }
 void query(String value){String q=value.toLowerCase(Locale.ROOT);catalog=BuiltInRegistries.ITEM.stream().filter(i->i!=Items.AIR&&(!filter.equals("ores")||i instanceof BlockItem bi&&SuitRuntime.ore(bi.getBlock().defaultBlockState()))&&(BuiltInRegistries.ITEM.getKey(i).toString().contains(q)||new ItemStack(i).getHoverName().getString().toLowerCase(Locale.ROOT).contains(q))).toList();page=0;}
 @Override public void extractContents(GuiGraphicsExtractor g,int mx,int my,float dt){int x=leftPos,y=topPos;g.fill(x-2,y-2,x+362,y+242,0xff0b1219);g.fill(x,y,x+360,y+240,0xff293641);g.fill(x+5,y+5,x+355,y+25,0xff17222b);for(var slot:menu.slots){g.fill(x+slot.x-1,y+slot.y-1,x+slot.x+17,y+slot.y+17,0xff89969e);g.fill(x+slot.x,y+slot.y,x+slot.x+16,y+slot.y+16,0xff11181e);}var d=SuitClient.data;for(var e:upgrades.entrySet()){var u=e.getValue();e.getKey().setMessage(Component.translatable("suit.upgrade."+u.id()).append(" "+d.level(u)+"/"+u.max));e.getKey().active=d.level(u)<u.max;}g.text(font,Energy.format(d.energy())+" / "+Energy.format(d.capacity())+" ТЕ",x+12,y+53,d.energy()==0?0xffe77f60:0xfff6c572);g.text(font,"+"+Energy.format(SuitClient.stationIn)+" ТЕ/с · капсулы "+d.contents().nutrients(),x+184,y+228,0xff8bddac);

  if(mx>=x+184&&my>=y+226&&my<y+240)g.setTooltipForNextFrame(font,List.of(Component.literal("Вход: "+Energy.format(SuitClient.stationIn,true)+" ТЕ/с, максимум 512"),Component.literal("В костюмы: "+Energy.format(SuitClient.chargeRate,true)+" ТЕ/с"),Component.literal("Буфер: "+Energy.format(SuitClient.stationEnergy)+" / 4096 ТЕ")),Optional.empty(),mx,my);
  if(!filter.isEmpty()&&!filter.equals("color")){var selected=filter.equals("ores")?d.contents().ores():d.contents().blacklist();for(int i=0;i<32;i++){int index=page*32+i,cx=x+186+(i%8)*21,cy=y+98+(i/8)*21;if(index>=catalog.size())break;var item=catalog.get(index);var stack=new ItemStack(item);boolean has=selected.contains(BuiltInRegistries.ITEM.getKey(item).toString());g.fill(cx-1,cy-1,cx+17,cy+17,has?0xffb87b2a:0xff16232e);g.item(stack,cx,cy);if(mx>=cx&&mx<cx+18&&my>=cy&&my<cy+18)g.setTooltipForNextFrame(font,stack,mx,my);}}
  super.extractContents(g,mx,my,dt);
  if(filter.isEmpty()){int row=0;for(var u:SuitUpgrade.values())if(u.branch.equals(branch)){int cy=y+74+row++*17;if(mx>=x+184&&mx<x+352&&my>=cy&&my<cy+18)g.setTooltipForNextFrame(font,List.of(Component.translatable("suit.upgrade."+u.id()),Component.literal("Уровень: "+d.level(u)+" / "+u.max),Component.literal(SuitDescriptions.detail(u))),Optional.empty(),mx,my);}}
 }
 @Override public boolean mouseClicked(MouseButtonEvent e,boolean twice){double x=e.x()-leftPos,y=e.y()-topPos;if(!filter.isEmpty()&&!filter.equals("color")&&x>=184&&x<352&&y>=97&&y<182){int index=page*32+(int)((y-97)/21)*8+(int)((x-184)/21);if(index<catalog.size())send(filter,BuiltInRegistries.ITEM.getKey(catalog.get(index)).toString());return true;}return super.mouseClicked(e,twice);}
 @Override protected void extractLabels(GuiGraphicsExtractor g,int x,int y){g.text(font,title,12,10,0xffe9eef2);}
}
